command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="5c4b2135a96563417246b32e6be801c4ad593930"
$candidate="a7b675f790356cc152c577a3d670e9829afdaae4"
$branch="work/removable-recycle-20261006"
$temp=Join-Path $env:RUNNER_TEMP ("fly-removable-recycle-"+$env:GITHUB_RUN_ID)
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "removable recycle fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before removable recycle acceptance"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "removable recycle candidate moved"}
if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp 2>$null;Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue}
& git worktree add --detach $temp $candidate
if($LASTEXITCODE -ne 0){throw "removable recycle worktree creation failed"}
try{
  Set-Location -LiteralPath $temp
  & git diff --check ($main+"..."+$candidate)
  if($LASTEXITCODE -ne 0){throw "removable recycle diff check failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
  if($LASTEXITCODE -ne 0){throw "removable recycle FAST failed"}

  & cmd /c tests\winui\m22\build.cmd Release
  if($LASTEXITCODE -ne 0){throw "M22 Release fixture build failed"}
  $env:FLY_M22_CONFIG="Release"
  & python -X utf8 tests\winui\m22\test_native.py
  if($LASTEXITCODE -ne 0){throw "M22 Release native acceptance failed"}
  Remove-Item Env:\FLY_M22_CONFIG -ErrorAction SilentlyContinue

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "canonical Release build failed"}

  & python -X utf8 tools\winui\run_checks.py gui --area file-operations --configuration Release
  if($LASTEXITCODE -ne 0){throw "file-operations GUI regression failed"}

  & python -X utf8 tests\winui\test_owned_recycle_gui.py --configuration Release --preflight
  if($LASTEXITCODE -eq 0){
    Write-Host "REMOVABLE_RECYCLE_FIXED_BIN_PREFLIGHT=EMPTY"
    & python -X utf8 tests\winui\test_owned_recycle_gui.py --configuration Release --apply-owned
    if($LASTEXITCODE -ne 0){throw "owned fixed-drive recycle+restore failed"}
    Write-Host "REMOVABLE_RECYCLE_FIXED_ACTUAL=PASS"
  }else{
    Write-Host "REMOVABLE_RECYCLE_FIXED_ACTUAL=NOT_RUN_BIN_NOT_EMPTY_OR_UNAVAILABLE"
  }

  Write-Host "REMOVABLE_RECYCLE_FAST=PASS"
  Write-Host "REMOVABLE_RECYCLE_M22_NATIVE=PASS"
  Write-Host "REMOVABLE_RECYCLE_RELEASE=PASS"
  Write-Host "REMOVABLE_RECYCLE_GUI=PASS"
  Write-Host "REMOVABLE_RECYCLE_PHYSICAL_USB=NOT_RUN_NO_DEVICE"
} finally {
  Set-Location -LiteralPath $repo
  Remove-Item Env:\FLY_M22_CONFIG -ErrorAction SilentlyContinue
  if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
  & git worktree prune
}
